def program(y1, y2):
    # Precondition (from the original docstring): y1 <= y2.
    y1 -= 1  # TARGET_A
    y2 -= 1
    return (y2//4 - y1//4) - (y2//100 - y1//100) + (y2//400 - y1//400)

def program(a, b):
    reverse = 0
    if a < 0:
        a *= -1  # TARGET_A
        reverse = 1
    if b < 0:
        b *= -1
    rv = a % b
    if reverse:
        rv *= -1
    return rv

flagOnCurve = 0x01
flagXShort = 0x02
flagYShort = 0x04
flagXsame = 0x10
flagYsame = 0x20


def program(x, y, onCurve):
    flag = flagOnCurve if onCurve else 0
    cost = 0
    if x == 0:
        flag = flag | flagXsame  # TARGET_A
    elif -255 <= x <= 255:
        flag = flag | flagXShort
        if x > 0:
            flag = flag | flagXsame
        cost += 1
    else:
        cost += 2
    if y == 0:
        flag = flag | flagYsame
    elif -255 <= y <= 255:
        flag = flag | flagYShort
        if y > 0:
            flag = flag | flagYsame
        cost += 1
    else:
        cost += 2
    return flag, cost

def program(length, start, end):
    if end > length:
        end = length
    if end < 0:
        end += length  # TARGET_A
        if end < 0:
            end = 0
    if start < 0:
        start += length
        if start < 0:
            start = 0
    return start, end

def program(a):
    """Return the given angle normalized to -180 < *a* <= 180 degrees."""
    a = (a + 360) % 360
    if a > 180:
        a = a - 360  # TARGET_A
    return a

def program(lo, hi, k=1):
    if lo + k < hi:
        mid = (hi + lo) // 2
        if k > 1:
            mid = mid - ((mid - hi) % k)  # TARGET_A
        return program(lo, mid, k) * program(mid + k, hi, k)
    elif lo + k == hi:
        return lo * hi
    else:
        return hi

def program(timestamp):
    timestamp = int(timestamp)
    if timestamp > 253402300799:
        timestamp //= 1000  # TARGET_A
    return timestamp

def program(delta, first, numchars):
    if first:
        delta //= 700
    else:
        delta //= 2
    delta += delta // numchars  # TARGET_A
    k = 0
    while delta > 455:
        delta //= 35
        k += 36
    return k + (36 * delta) // (delta + 38)
